private val dynamicSpanishFragments = listOf(
    Regex("^GPS path so far (\\d+) m\\.") to "Recorrido GPS hasta ahora: \$1 m.",
    Regex("^GPS path (\\d+) m\\. Signatures only, class Show only, Named radios only, or Watched only is also on, so only those radios can co-travel\\.") to
        "Recorrido GPS: \$1 m. También está activado Solo firmas, Mostrar solo por clase, Solo radios con nombre o Solo seguidos, así que solo esas radios pueden acompañarte.",
    Regex("^GPS path (\\d+) m\\. Loud BLE heard along that path at a fairly steady level — not ones that only appear when you arrive\\.") to
        "Recorrido GPS: \$1 m. Se detectó una señal BLE intensa y relativamente estable durante el trayecto, no solo al llegar.",
)

internal fun translateAppText(text: String, language: AppLanguage): String {
    if (language != AppLanguage.SPANISH) return text
    spanish[text]?.let { return it }
    for ((pattern, replacement) in dynamicSpanish) {
        if (pattern.matches(text)) return pattern.replace(text, replacement)
    }
    for ((pattern, replacement) in dynamicSpanishFragments) {
        if (pattern.containsMatchIn(text)) return pattern.replace(text, replacement)
    }
    if (text.startsWith("Feed status  · ")) {
        return text
            .replaceFirst("Feed status  · ", "Estado del flujo · ")
            .replace("paused (Privacy mode)", "en pausa (modo de privacidad)")
            .replace("no send yet this session", "sin envíos en esta sesión")
            .replace("error:", "error:")
            .replace("on the feed ", "en el flujo ")
            .replace("sent ", "enviados ")
            .replace(" gone", " desaparecidos")
    }
    Regex("^(.+) · (\\d+) rules · (\\d+) live · (OR|AND)$").matchEntire(text)?.let { match ->
        val kind = spanish[match.groupValues[1]] ?: match.groupValues[1]
        val conjunction = if (match.groupValues[4] == "OR") "O" else "Y"
        return "$kind · ${match.groupValues[2]} reglas · ${match.groupValues[3]} activas · $conjunction"
    }
    if (text.endsWith(" · OR") || text.endsWith(" · AND")) {
        val translatedKind = text.substringBefore(" · ").let {
            spanish[it] ?: it
        }
        return Regex("^.+ · (\\d+) rules · (\\d+) live · (OR|AND)$")
            .matchEntire(text)
            ?.let { match ->
                "$translatedKind · ${match.groupValues[1]} reglas · ${match.groupValues[2]} activas · " +
                    if (match.groupValues[3] == "OR") "O" else "Y"
            }
            ?: text
    }
    val withMappedFragments = spanish.entries
        .asSequence()
        .filter { it.key.length >= 30 && text.contains(it.key) }
        .sortedByDescending { it.key.length }
        .fold(text) { translated, (english, spanish) -> translated.replace(english, spanish) }
    return spanishFragments.fold(withMappedFragments) { translated, (english, spanish) ->
        translated.replace(english, spanish)
    }
}

@Composable
fun localizeAppText(text: String): String = translateAppText(text, LocalAppLanguage.current)

@Composable
fun AppText(
    text: String,
    modifier: Modifier = Modifier,
    color: Color = Color.Unspecified,
    fontSize: TextUnit = TextUnit.Unspecified,
    fontStyle: FontStyle? = null,
    fontWeight: FontWeight? = null,
    fontFamily: FontFamily? = null,
    letterSpacing: TextUnit = TextUnit.Unspecified,
    textDecoration: TextDecoration? = null,
    textAlign: TextAlign? = null,
    lineHeight: TextUnit = TextUnit.Unspecified,
    overflow: TextOverflow = TextOverflow.Clip,
    softWrap: Boolean = true,
    maxLines: Int = Int.MAX_VALUE,
    minLines: Int = 1,
    onTextLayout: (TextLayoutResult) -> Unit = {},
    style: TextStyle = LocalTextStyle.current,
) {
    MaterialText(
        text = translateAppText(text, LocalAppLanguage.current),
        modifier = modifier,
        color = color,
        fontSize = fontSize,
        fontStyle = fontStyle,
        fontWeight = fontWeight,
        fontFamily = fontFamily,
        letterSpacing = letterSpacing,
        textDecoration = textDecoration,
        textAlign = textAlign,
        lineHeight = lineHeight,
        overflow = overflow,
        softWrap = softWrap,
        maxLines = maxLines,
        minLines = minLines,
        onTextLayout = onTextLayout,
        style = style,
    )
}

